<?php require_once 'config.php';$pageTitle='Announcements';$items=db()->query('SELECT a.*,u.name author FROM announcements a LEFT JOIN users u ON u.id=a.created_by ORDER BY a.created_at DESC')->fetchAll();require 'includes/header.php'; ?><section class="page-heading"><span class="eyebrow">WHAT'S HAPPENING</span><h1>Platform <em>announcements.</em></h1><p>Updates, opportunities and important messages from your learning community.</p></section><section class="section"><div class="announcement-list"><?php foreach($items as $a): ?><article><span class="announcement-mark">✦</span><div><h3><?= e($a['title']) ?></h3><p><?= nl2br(e($a['body'])) ?></p><small><?= e($a['author']??'Platform team') ?> · <?= e(date('d M Y',strtotime($a['created_at']))) ?></small></div></article><?php endforeach; ?><?php if(!$items): ?><div class="empty-state"><span>✦</span><h3>It's quiet for now</h3><p>New platform announcements will appear here.</p></div><?php endif; ?></div></section><?php require 'includes/footer.php'; ?>
